const d = $json;
  for (const key of ['review_id', 'source_type', 'source_reference', 'source_text', 'proposed_text', 'google_warning', 'reviewer_email']) {
    if (!String(d[key] ?? '').trim()) throw new Error(`Missing required review field: ${key}`);
  }
  const reviewer = String(d.reviewer_email).trim().toLowerCase();
  if (reviewer !== 'dustin.boggess@gmail.com') throw new Error('Unexpected review recipient.');
  const expires = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();
  return [{ json: {
    review_id: String(d.review_id).trim(),
    status: 'review_pending',
    source_type: String(d.source_type).trim(),
    source_reference: String(d.source_reference).trim(),
    source_text: String(d.source_text),
    proposed_text: String(d.proposed_text),
    image_url: String(d.image_url ?? '').trim(),
    google_warning: String(d.google_warning),
    reviewer_email: reviewer,
    expires_at: expires,
    decision: '',
    decision_notes: '',
    decided_at: '',
    approver: '',
    google_post_id: '',
    publish_result: 'not_published',
    reminder_at: '',
  } }];

const candidate = $('Validate and Set Expiry').item.json;
  const existing = $json && $json.review_id ? $json : null;
  return [{ json: {
    ...candidate,
    is_duplicate: Boolean(existing),
    existing_status: String(existing?.status ?? ''),
  } }];

const source = $('Hash Stored Token').item.json;
  const base = 'https://refurb.tail0ab4d2.ts.net:5678/webhook/fsv-google-review';
  const reviewLink = (action) => `${base}?review_id=${encodeURIComponent(source.review_id)}&action=${encodeURIComponent(action)}&token=${encodeURIComponent(source.approval_token)}`;
  const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  const lines = (value) => escapeHtml(value).replace(/\r?\n/g, '<br>');
  const imageUrl = String(source.image_url ?? '').trim();
  const safeImageUrl = /^https?:\/\//i.test(imageUrl) ? imageUrl : '';
  const imageSection = safeImageUrl
    ? `<p style="margin:20px 0 8px;font-weight:700">Image</p><p style="margin:0 0 20px"><a href="${escapeHtml(safeImageUrl)}" rel="noopener noreferrer"><img src="${escapeHtml(safeImageUrl)}" alt="Proposed post image" style="display:block;max-width:100%;height:auto;border:1px solid #d8dee8;border-radius:8px"></a></p>`
    : '<p style="margin:20px 0;color:#667085"><strong>Image:</strong> No image supplied.</p>';
  const approveLink = reviewLink('APPROVE');
  const editLink = reviewLink('EDIT');
  const skipLink = reviewLink('SKIP');
  const subject = `[${source.review_id}] Google Business draft ready for review`;
  const emailHtml = `<!doctype html><html><body style="margin:0;background:#f4f6f8;font-family:Arial,sans-serif;color:#182230"><div style="max-width:680px;margin:0 auto;padding:24px"><div style="background:#ffffff;border:1px solid #d8dee8;border-radius:12px;padding:28px"><h1 style="margin:0 0 8px;font-size:24px">Full Steam Vapor post review</h1><p style="margin:0 0 24px;color:#667085">Review ID: <strong>${escapeHtml(source.review_id)}</strong></p><p style="margin:0 0 8px;font-weight:700">Source</p><p style="margin:0 0 8px"><strong>${escapeHtml(source.source_type)}</strong> — ${escapeHtml(source.source_reference)}</p><div style="padding:14px;background:#f8fafc;border-radius:8px;line-height:1.5">${lines(source.source_text)}</div><p style="margin:20px 0 8px;font-weight:700">Proposed Google Business wording</p><div style="padding:14px;background:#eef7ff;border:1px solid #c7e0f4;border-radius:8px;line-height:1.5">${lines(source.proposed_text)}</div>${imageSection}<p style="margin:20px 0 8px;font-weight:700">Google compatibility note</p><div style="padding:14px;background:#fff8e7;border:1px solid #f3d28a;border-radius:8px;line-height:1.5">${lines(source.google_warning)}</div><p style="margin:24px 0 12px">Choose an option below. Each link opens a separate confirmation page; the first click never changes status.</p><p style="margin:0 0 20px"><a href="${approveLink}" style="display:inline-block;margin:0 8px 8px 0;padding:12px 18px;background:#18794e;color:#ffffff;text-decoration:none;border-radius:7px;font-weight:700">Approve</a><a href="${editLink}" style="display:inline-block;margin:0 8px 8px 0;padding:12px 18px;background:#b54708;color:#ffffff;text-decoration:none;border-radius:7px;font-weight:700">Edit</a><a href="${skipLink}" style="display:inline-block;margin:0 8px 8px 0;padding:12px 18px;background:#475467;color:#ffffff;text-decoration:none;border-radius:7px;font-weight:700">Skip</a></p><p style="margin:0;color:#667085;font-size:13px">This signed, single-use review link expires ${escapeHtml(source.expires_at)}. Publishing is not connected.</p></div></div></body></html>`;
  return [{ json: {
    review_id: source.review_id,
    reviewer_email: source.reviewer_email,
    subject,
    email_html: emailHtml,
    delivery_state: 'READY_TO_SEND',
    publishing_state: 'NOT_CONNECTED',
  } }];
